import React, { useState, useEffect } from 'react';

const FeaturedCarousel = ({ properties = [], onViewDetails }) => {
  const [activeIndex, setActiveIndex] = useState(0);
  
  // تصفية العقارات المميزة (مثلاً السعر أعلى من 2 مليون أو لها حالة خاصة)
  const featured = properties.filter(p => p.price > 2000000 || p.featured).slice(0, 5);
  
  // إذا لم توجد عقارات مميزة، لا نعرض القسم
  if (featured.length === 0) return null;

  const nextSlide = () => setActiveIndex((prev) => (prev + 1) % featured.length);
  const prevSlide = () => setActiveIndex((prev) => (prev - 1 + featured.length) % featured.length);

  // تشغيل تلقائي
  useEffect(() => {
    const interval = setInterval(nextSlide, 5000);
    return () => clearInterval(interval);
  }, [featured.length]);

  const activeProp = featured[activeIndex];

  if (!activeProp) return null;

  return (
    <div className="featured-carousel-container my-5 position-relative overflow-hidden py-4 bg-light bg-opacity-50">
       <div className="container">
          <div className="d-flex justify-content-between align-items-end mb-4">
              <div>
                  <h6 className="text-warning fw-bold text-uppercase letter-spacing-2">نخبة العقارات</h6>
                  <h2 className="fw-bold display-6">⭐ عقارات مميزة</h2>
              </div>
              <div className="d-flex gap-2">
                  <button className="btn btn-outline-dark rounded-circle shadow-sm" onClick={prevSlide} style={{width: 40, height: 40}}>←</button>
                  <button className="btn btn-outline-dark rounded-circle shadow-sm" onClick={nextSlide} style={{width: 40, height: 40}}>→</button>
              </div>
          </div>
          
          <div className="row align-items-center">
             <div className="col-lg-7 position-relative mb-4 mb-lg-0">
                <div className="featured-image-container rounded-4 shadow-lg overflow-hidden position-relative" style={{height: '450px'}}>
                   <img 
                     src={activeProp.imageUrl || (activeProp.images && activeProp.images[0])} 
                     alt={activeProp.type} 
                     className="w-100 h-100 object-fit-cover transition-img"
                     key={activeProp.id} // مفتاح لتفعيل الأنيميشن عند التغيير
                   />
                   <div className="position-absolute top-0 start-0 m-4 badge bg-warning text-dark shadow px-3 py-2 fs-6">💎 فرصة استثمارية</div>
                   <div className="position-absolute bottom-0 start-0 w-100 h-50" style={{background: 'linear-gradient(to top, rgba(0,0,0,0.6), transparent)'}}></div>
                </div>
             </div>
             <div className="col-lg-5">
                <div className="featured-content p-4 p-md-5 bg-white rounded-4 shadow-lg position-relative fade-in-up" style={{marginLeft: '-80px', zIndex: 2}}>
                   <div className="d-flex align-items-center mb-2">
                      <span className="badge bg-primary bg-opacity-10 text-primary me-2">{activeProp.type}</span>
                      <span className="text-muted small">📍 {activeProp.location?.city}</span>
                   </div>
                   <h2 className="fw-bold mb-2 text-dark">{activeProp.location?.neighborhood}</h2>
                   <p className="text-primary fw-bold display-6 mb-3">{activeProp.price?.toLocaleString()} <span className="fs-6 text-muted">جنيه</span></p>
                   <p className="text-muted mb-4" style={{lineHeight: '1.8'}}>{activeProp.description?.substring(0, 120)}...</p>
                   
                   <div className="d-flex justify-content-between mb-4 text-muted small border-top border-bottom py-3">
                      <div className="text-center">
                          <div className="fw-bold text-dark fs-5">{activeProp.area}</div>
                          <span>متر مربع</span>
                      </div>
                      <div className="vr"></div>
                      <div className="text-center">
                          <div className="fw-bold text-dark fs-5">{activeProp.rooms}</div>
                          <span>غرف</span>
                      </div>
                      <div className="vr"></div>
                      <div className="text-center">
                          <div className="fw-bold text-dark fs-5">{activeProp.bathrooms}</div>
                          <span>حمام</span>
                      </div>
                   </div>
                   
                   <button className="btn btn-dark w-100 rounded-pill py-3 fw-bold shadow hover-scale" onClick={() => onViewDetails && onViewDetails(activeProp)}>
                      عرض التفاصيل الكاملة ↗
                   </button>
                </div>
             </div>
          </div>
       </div>
       <style>{`
         .transition-img { animation: zoomFade 0.8s cubic-bezier(0.25, 0.46, 0.45, 0.94); }
         @keyframes zoomFade { from { opacity: 0.8; transform: scale(1.05); } to { opacity: 1; transform: scale(1); } }
         @media (max-width: 991px) {
            .featured-content { margin-left: 0 !important; margin-top: -60px; width: 90%; margin-right: auto; margin-left: auto; }
         }
       `}</style>
    </div>
  );
};

export default FeaturedCarousel;
